#define GPIO_B_MODER	(*(volatile uint32_t*) GPIO_B)
#define GPIO_B_AFRH 	(*(volatile uint32_t*) (GPIO_B + 0x24))

// define GPIO C registers
#define GPIO_C_MODER 	(*(volatile uint32_t*) GPIO_C)
