#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif

volatile uint32_t press_counter = 0;
volatile uint32_t timer_counter = 0;

void EXTI15_10_IRQHandler(void) {
	if (EXTI_PR & (1U << 13)) {
		EXTI_PR = (1U <<13);
		press_counter = (press_counter + 1) % 3;
	}
}

void turn_LD2_off(void) {
	GPIO_A_BSRR |= (0x1U << 21);
}

void turn_LD2_on(void) {
	GPIO_A_BSRR |= (0x1U << 5);
}

void toggle_LD2(void) {
	// if the value at the LEDregister is 1 --> resets the bit

	if (press_counter == 2) {
		if (GPIO_A_ODR & (0x1U<<5)) {
			turn_LD2_off();
		}
		else { //if the value at the LED register is 0 --> sets the bit
			turn_LD2_on();
		}
	}
}

void TIM8_BRK_TIM12_IRQHandler(void){
	if (TIM12_SR & (1U << 0)) {
		timer_counter = (timer_counter + 1) % 3;

		if (timer_counter == 2) {
			toggle_LD2();
		}

		NVIC_ICPR_1 |= (1U << 11);
		TIM12_SR &= ~(1U << 0);
	}
}

void GPIO_A_setup(void) {

	//set up GPIO_A pin for LED
	GPIO_A_MODER &= ~(3U<<10);
	GPIO_A_MODER |= (1U<<10);
}

void GPIO_B_setup(void) {

	// set up GPIO pin for timer
	GPIO_B_MODER &= ~(3U<<30);
	GPIO_B_MODER |= (2U<<30);

	// set up AF mode
	GPIO_B_AFRH &= ~(0xFU<<28);
	GPIO_B_AFRH |= (0x9U<<28);
}

void GPIO_C_setup(void) {
	// set up GPIO_C pin
	GPIO_C_MODER &= ~(3U<< 26);

	// set up input mode for the GPIOC, pin 13
	GPIO_C_PUPDR |= (1U << 26);
}

// turn on RCC
void RCC_setup(void) {
	// turn on RCC for button and LED
	RCC_AHB1_EN |= (1U << 2);
	RCC_AHB1_EN |= (1U << 0);

	// enable RCC for TIM12
	RCC_APB1_EN |= (1U << 6);

	//enable RCC for SYSCFG
	RCC_APB2_EN |= (1U << 14);
}

void setup_NVIC_EXTI(void) {
	// configure EXTI line
	EXTI_IMR |= (1U << 13);
	EXTI_FTSR |= (1U << 13);

	// configure EXTI control register
	SYSCFG_EXTICR4 &= ~(0xFU << 4);
	SYSCFG_EXTICR4 |= (1U << 5);

	// set up NVIC
	NVIC_ISER_1 |= (1U << 8);
}

void TIM12_setup(void) {
	// clear the TIM12 control register
	TIM12_CR1 &= ~(0x1U << 7);
	TIM12_CR1 &= ~(0x1U << 0);

	//set up TIM12 CR register
	TIM12_CR1 |= (0x1U << 7);
	TIM12_CR1 |= (0x1U << 0);

	// set up the DIER
	TIM12_DIER &= ~(0x1U << 0);
	TIM12_DIER |= (0x1U << 0);
	// we need to read from TIM12_SR to get update interrupt event
	TIM12_PSC = 1600 - 1;
	TIM12_ARR = 1000 - 1;
}

void setup_NVIC_TIM12(void) {
	NVIC_ISER_1 |= (0x1 << 11);
}

int main(void)
{
	// begin setup
	RCC_setup();
	// resetting BR5 register
	GPIO_A_BSRR |= (0x1U << 5);
	GPIO_A_setup();
	GPIO_B_setup();
	GPIO_C_setup();
	setup_NVIC_EXTI();
	TIM12_setup();
	setup_NVIC_TIM12();

	turn_LD2_off();
	turn_LD2_on();

    /* Loop forever */
	while (1) {
		switch(press_counter) {
		case 0:
			turn_LD2_off();
			break;
		case 1:
			turn_LD2_on();
			break;
		case 2:
			break;
		}
	}
}
